
import bpy, base64, os, math, tempfile, mathutils
IMGS = {"profile": "", "plan": "", "body_plan": ""}
SETUP = {"REF_profile": ["profile", 785, 4.918839153959666, [759, 27], [90, 0, 0], [0.0, 1.0, 0.0]], "REF_plan": ["plan", 785, 4.918839153959666, [762, 8], [0, 0, 0], [0.0, 0.0, -0.05]], "REF_body_plan": ["body_plan", 500, 3.067484662576687, [248, 35], [90, 0, 90], [0.6, 0.0, 0.0]]}
STATIONS_MM = [0, 400, 800, 1200, 1800, 2400, 3000, 3600]
folder = os.path.join(tempfile.gettempdir(), "hull_refs")
os.makedirs(folder, exist_ok=True)
# hide the earlier (estimated) hull
old = bpy.data.collections.get("Hull_Cathedral")
if old: old.hide_viewport = True
col = bpy.data.collections.get("Hull_References") or bpy.data.collections.new("Hull_References")
if col.name not in bpy.context.scene.collection.children: bpy.context.scene.collection.children.link(col)
for ob in list(col.objects): bpy.data.objects.remove(ob, do_unlink=True)
out = {}
for name, (key, wpx, mmpx, (u, v), rot, anchor) in SETUP.items():
    path = os.path.join(folder, key + ".png")
    with open(path, "wb") as f: f.write(base64.b64decode(IMGS[key]))
    img = bpy.data.images.load(path, check_existing=True); img.reload(); img.pack()
    S = wpx * mmpx / 1000.0
    e = bpy.data.objects.new(name, None)
    e.empty_display_type = "IMAGE"; e.data = img
    e.empty_display_size = S
    e.empty_image_offset = (0.0, 0.0)
    e.use_empty_image_alpha = True; e.color[3] = 0.6
    e.show_empty_image_only_axis_aligned = True
    e.rotation_euler = [math.radians(a) for a in rot]
    col.objects.link(e)
    # move so the anchor pixel lands on the world anchor
    k = mmpx / 1000.0
    R = e.rotation_euler.to_matrix()
    local = mathutils.Vector((u * k, v * k, 0.0))
    e.location = mathutils.Vector(anchor) - R @ local
    out[name] = {"size_m": round(S, 3), "loc": [round(c, 3) for c in e.location]}
# station guide lines (bow at X=0, stern toward -X), baseline Z=0, centreline Y=0
mesh = bpy.data.meshes.new("Stations")
verts, edges = [], []
for x in STATIONS_MM:
    X = -x / 1000.0
    i = len(verts); verts += [(X, 0, 0), (X, 0, 0.7), (X, 0.8, 0)]; edges += [(i, i+1), (i, i+2)]
verts += [(0.2, 0, 0), (-3.8, 0, 0)]; edges += [(len(verts)-2, len(verts)-1)]
mesh.from_pydata(verts, edges, [])
g = bpy.data.objects.new("Station_Guides", mesh); col.objects.link(g)
for area in bpy.context.screen.areas:
    if area.type == "VIEW_3D":
        for region in area.regions:
            if region.type == "WINDOW":
                with bpy.context.temp_override(area=area, region=region):
                    bpy.ops.view3d.view_axis(type="FRONT")
                    r3d = area.spaces.active.region_3d
                    r3d.view_location = (-1.8, 0, 0.3); r3d.view_distance = 4.5
                break
result = out
